),
all_tx AS (SELECT * FROM evm UNION ALL SELECT * FROM stl),

agg AS (
  SELECT
    count(*)  FILTER (WHERE tx_type <> 'fee')                      AS transactions,
    sum(usdc) FILTER (WHERE tx_type <> 'fee')                      AS usdc_volume,
    sum(usdc) FILTER (WHERE tx_type = 'transfer')                  AS usdc_sent,
    sum(usdc) FILTER (WHERE tx_type = 'deposit')                   AS usdc_deposited,
    count(*)  FILTER (WHERE tx_type IN ('bridge_in','bridge_out')) AS bridge_movements,
    count(DISTINCT chain) FILTER (WHERE tx_type <> 'fee')          AS chains
  FROM all_tx
)

-- One row per metric, so a single Table visualisation renders the whole counter row with no
-- configuration. The wide one-row form needed six separately configured Counters, and every
-- other chart type drew nonsense from it -- a pie of one row plots first_activity's epoch
-- milliseconds as if it were a quantity.
SELECT metric, value
FROM (
  SELECT 1 AS ord, 'Transactions'     AS metric, CAST(transactions      AS DOUBLE) AS value FROM agg
  UNION ALL SELECT 2, 'Volume (USDC)',           usdc_volume                              FROM agg
  UNION ALL SELECT 3, 'Sent (USDC)',             usdc_sent                                FROM agg
  UNION ALL SELECT 4, 'Deposited (USDC)',        usdc_deposited                           FROM agg
  UNION ALL SELECT 5, 'Bridge movements', CAST(bridge_movements AS DOUBLE)                FROM agg
  UNION ALL SELECT 6, 'Chains',           CAST(chains           AS DOUBLE)                FROM agg
)
ORDER BY ord
